<?php require __DIR__.'/../config/bootstrap.php';require_role('admin');$rows=$pdo->query("SELECT p.*,u.full_name,c.title FROM payments p JOIN users u ON u.id=p.user_id JOIN courses c ON c.id=p.course_id ORDER BY p.created_at DESC")->fetchAll();$page_title='Payments';require __DIR__.'/../includes/header.php';?>
<h1 class="text-3xl font-bold">Payment transactions</h1><div class="overflow-x-auto bg-white border rounded-xl mt-6"><table class="w-full text-sm"><thead class="bg-slate-100"><tr><?php foreach(['Student','Course','Provider','Reference','Receipt','Amount','Status','Created'] as $h): ?><th class="p-3 text-left"><?= $h ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr class="border-t"><td class="p-3"><?= e($r['full_name']) ?></td><td class="p-3"><?= e($r['title']) ?></td><td class="p-3"><?= e($r['provider']) ?></td><td class="p-3"><?= e($r['reference']) ?></td><td class="p-3"><?= e($r['provider_receipt']??'—') ?></td><td class="p-3"><?= money((int)$r['amount_kes']) ?></td><td class="p-3"><?= e($r['status']) ?></td><td class="p-3"><?= e($r['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>
